//! SLH-DSA known-answer test vectors.
//!
//! Extracted from the NIST ACVP server reference data for FIPS 205
//! (`SLH-DSA-keyGen-FIPS205` and `SLH-DSA-sigGen-FIPS205`,
//! `internalProjection.json`), see
//! <https://github.com/usnistgov/ACVP-Server/tree/master/gen-val/json-files>
//!
//! Of the signature generation vectors, a few of the shortest messages of each
//! parameter set are kept: one deterministic and one hedged per interface, and
//! one per pre hash function this crate implements.

use super::PreHash;

/// Key generation vector: the seed `SK.seed || SK.prf || PK.seed` and the
/// expected keys
pub(super) struct KeyGen<const SEED: usize, const SK: usize, const VK: usize> {
    pub seed: [u8; SEED],
    pub sk: [u8; SK],
    pub vk: [u8; VK],
}

/// How a signature generation vector frames its message
#[derive(Clone, Copy, Debug)]
pub(super) enum Interface {
    /// `slh_sign_internal` over the message as is, without a context
    Internal,
    /// `slh_sign`, the pure variant
    Pure,
    /// `hash_slh_sign`, the pre hash variant
    PreHash(PreHash),
}

/// Signature generation vector, holding the signing key it was made with and
/// the SHA3-256 digest of the expected signature.
///
/// `rnd` is `None` for the deterministic variant, which FIPS 205 defines as
/// signing with `PK.seed` as the randomness.
pub(super) struct SigGen<const SK: usize, const N: usize> {
    pub sk: [u8; SK],
    pub interface: Interface,
    pub message: &'static [u8],
    pub context: &'static [u8],
    pub rnd: Option<[u8; N]>,
    pub signature_sha3_256: [u8; 32],
}

